"""Sixteen real demo handoffs, without synthetic AI memory or throw intent."""
from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];O=R/'qa/clinch';O.mkdir(parents=True,exist_ok=True);html=(R/'dist/INK-Street-Fighter-6.html').read_bytes()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page();errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html.decode());p.wait_for_function('window.INKDuel?.ready&&INK.Clinch')
 runs=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state,out=[];for(let seed=1;seed<=16;seed++){document.getElementById('difficulty').value='hard';A.start('ryu','ken','demo','classic',seed);G.paused=true;A.teleport(0,200);A.teleport(1,1240);A.step(40);G.mode='training';document.getElementById('dummy').value='idle';document.getElementById('infinite').checked=false;document.getElementById('autohp').checked=false;A.step(140);A.teleport(0,560);A.teleport(1,690);G.mode='demo';const choices=[],violations=[];let privatePlan=false,techs=0;for(let i=0;i<130;i++){const old=A.fighters.map(f=>({episode:f._inkClinchAI?.episode||0,until:f.ai?.plan?.until||0,next:f.ai?.nextDecision||0})),tick=G.tick;A.step();for(const [index,f]of A.fighters.entries()){const q=f._inkClinchAI;privatePlan||=!!q&&['techPlan','techUntil','techStart'].some(k=>Object.hasOwn(q,k));if((q?.episode||0)>old[index].episode){choices.push({actor:index,choice:q.choice});if(old[index].until>G.tick||old[index].next>G.tick)violations.push({actor:index,until:old[index].until,next:old[index].next,tick:G.tick});}}}techs=INK.Clinch.inspect().filter(e=>e.result==='tech').length;out.push({seed,choices,violations,privatePlan,techs});}return out;}''');b.close()
choices={c['choice'] for r in runs for c in r['choices']};rows=[{'name':'real demo produces strike throw and retreat episodes','passed':{'strike','throw','retreat'}<=choices,'choices':sorted(choices)},{'name':'episode choices respect existing plan and decision deadlines','passed':all(not r['violations'] for r in runs)},{'name':'no private free tech-plan fields','passed':all(not r['privatePlan'] for r in runs)}]
(O/'cpu.json').write_text(json.dumps({'htmlSha256':hashlib.sha256(html).hexdigest(),'rows':rows,'runs':runs,'errors':errors},indent=2)+'\n');print(rows);assert all(r['passed'] for r in rows) and not errors,errors
